@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity : float
}

class Dish {
  + name : string
  + id : int
}

class Table {
  + id : int
  + max_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + tax_id : string
  + name : string
  + address : string
}

class DishInMeal {
  + quantity : int
}

class DishIngredient {
  + quantity : float
}

Dish "*" -- "*" Ingredient : contains
Dish "1" -- "*" DishIngredient
Ingredient "1" -- "*" DishIngredient
Meal "1" -- "*" DishInMeal
Dish "1" -- "*" DishInMeal
Meal "0..1" -- "1" Client : consumed by
Meal "*" -- "1" Table : takes place at
Meal "*" -- "1" Waiter : responsible waiter

@enduml

